<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';
import {pmsFetch} from './loading';
import PmsFormDialog from './PmsFormDialog.vue';
import PmsTableControls from './PmsTableControls.vue';
const props=defineProps<{csrf?:string;permissions:string[]}>();const emit=defineEmits(['open','changed']);
const clients=ref<any[]>([]),companies=ref<any[]>([]),editor=ref<any>(null),error=ref(''),busy=ref(false),search=ref(''),page=ref(1),size=ref(10),company=ref('');
const can=(k:string)=>props.permissions.includes('*')||props.permissions.includes(k);
const filtered=computed(()=>clients.value.filter(c=>(!company.value||String(c.company_id)===company.value)&&(c.name+' '+c.company?.name+' '+(c.email||'')).toLowerCase().includes(search.value.toLowerCase())));
const shown=computed(()=>size.value<0?filtered.value:filtered.value.slice((page.value-1)*size.value,page.value*size.value));
async function api(path:string,method='GET',body?:any){const r=await pmsFetch('/pms/api/'+path,{method,headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(Object.values(d.errors||{}).flat().join(' ')||d.message||'Unable to complete this action.');return d;}
async function load(){try{const d=await api('clients');clients.value=d.clients;companies.value=d.companies;}catch(e){error.value=(e as Error).message;}}
function edit(c?:any){error.value='';editor.value=c?{...c}:{company_id:companies.value[0]?.id||'',name:'',email:'',phone:'',website:'',description:'',status:true};}
async function save(){busy.value=true;error.value='';try{await api('clients'+(editor.value.id?'/'+editor.value.id:''),'POST',editor.value);editor.value=null;await load();emit('changed');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function remove(c:any){if(!confirm('Delete client '+c.name+'?'))return;try{await api('clients/'+c.id,'DELETE');await load();emit('changed');}catch(e){error.value=(e as Error).message;}}
onMounted(load);
</script>
<template><div><div class="pms-hierarchy-heading"><div><small class="text-muted">WORKSPACE / CLIENTS</small><h3>Clients</h3><p class="text-muted">Manage clients and open their projects.</p></div></div><p v-if="error&&!editor" class="notice admin-error" role="alert">{{error}}</p><div class="pms-table-card"><div class="pms-table-heading"><button v-if="can('client-add')" class="button primary" @click="edit()"><i aria-hidden="true" class="ti ti-circle-plus"></i>Create client</button></div><PmsTableControls :total="filtered.length" v-model:search="search" v-model:page="page" v-model:size="size"><select v-model="company" aria-label="Filter company" @change="page=1"><option value="">All companies</option><option v-for="c in companies" :value="String(c.id)" :key="c.id">{{c.name}}</option></select></PmsTableControls><div class="pms-table-scroll"><table class="pms-table"><thead><tr><th>Client</th><th>Company</th><th>Email</th><th>Projects</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="c in shown" :key="c.id"><td><button class="pms-project-link" @click="emit('open',c.id)">{{c.name}}</button></td><td>{{c.company?.name}}</td><td>{{c.email||'?'}}</td><td>{{c.projects_count}}</td><td><span class="badge" :class="c.status?'bg-label-success':'bg-label-danger'">{{c.status?'Active':'Inactive'}}</span></td><td><div class="row-actions"><button class="pms-icon-action btn btn-sm btn-icon text-primary" v-if="can('client-edit')" :aria-label="'Edit '+c.name" @click="edit(c)"><i aria-hidden="true" class="ti ti-edit"></i></button><button class="pms-icon-action btn btn-sm btn-icon text-danger" v-if="can('client-trash')" :aria-label="'Delete '+c.name" @click="remove(c)"><i aria-hidden="true" class="ti ti-trash"></i></button></div></td></tr><tr v-if="!shown.length"><td colspan="6">No clients found.</td></tr></tbody></table></div><PmsTableControls footer :total="filtered.length" v-model:page="page" v-model:size="size"/></div><PmsFormDialog v-if="editor" :title="editor.id?'Edit client':'Create client'" centered @close="editor=null"><form class="pms-reference-form" @submit.prevent="save"><p v-if="error" class="notice admin-error full-width" role="alert">{{error}}</p><label class="full-width">Company<select v-model.number="editor.company_id" required><option disabled value="">Select company</option><option v-for="c in companies" :value="c.id" :key="c.id">{{c.name}}</option></select></label><label class="full-width">Client name<input v-model="editor.name" required maxlength="255"></label><label>Email<input v-model="editor.email" type="email"></label><label>Phone<input v-model="editor.phone" maxlength="50"></label><label class="full-width">Website<input v-model="editor.website" type="url"></label><label class="full-width">Description<textarea v-model="editor.description" rows="3"></textarea></label><label>Status<select v-model="editor.status"><option :value="true">Active</option><option :value="false">Inactive</option></select></label><div class="editor-actions"><button type="button" class="button" @click="editor=null">Cancel</button><button class="button primary" :disabled="busy">Save client</button></div></form></PmsFormDialog></div></template>
